import React, { useState } from 'react'
import { Button, Modal, Icon, message } from 'antd'
import 'codemirror/lib/codemirror.css'
import 'codemirror/theme/material.css'
import 'codemirror/mode/xml/xml'
import { Controlled as CodeMirror } from 'react-codemirror2'
import EditorWrapper from './style'

const HtmlPreviewModal = ({
  closeModal,
  isOpen,
  htmlContent,
  handleHtmlContentChange,
  htmlContentData,
  editDocumentRequest,
  LOADER,
  onlyView
}) => {
  const [previewState, setPreviewState] = useState(false)

  const handleEditDoc = () => {
    editDocumentRequest({
      body: {
        ...htmlContentData,
        html: htmlContent
      }
    })
  }

  const handleChange = (editor, data, value) => {
    handleHtmlContentChange(value)
  }

  const handleCopy = () => {
    navigator.clipboard.writeText(htmlContent)
    message.success('Copied', 0.5)
  }

  const srcDoc = `
    <html>
      ${htmlContent}
    </html>
  `

  return (
    <Modal
      title='HTML Editor'
      visible={isOpen}
      onCancel={() => {
        setPreviewState(false)
        closeModal()
      }}
      width={800}
      footer={null}
    >
      <EditorWrapper>
        <div className='code-header'>
          <Button onClick={() => setPreviewState(!previewState)} type='primary'>
            {previewState ? 'Html' : 'Preview'}
          </Button>
          {!previewState && (
            <Icon
              type='copy'
              className='icon'
              theme='filled'
              onClick={handleCopy}
            />
          )}
        </div>
        <>
          {!previewState
            ? (
              <CodeMirror
                onBeforeChange={handleChange}
                value={htmlContent}
                className='code-mirror-wrapper'
                options={{
                  lineWrapping: true,
                  lint: true,
                  theme: 'material',
                  mode: 'xml',
                  lineNumbers: true
                }}
              />
              )
            : (
              <iframe title='output' srcDoc={srcDoc} className='output-wrapper' />
              )}
        </>
        <div className='btn-section'>
          {!onlyView && <Button type='primary' onClick={handleEditDoc} loading={LOADER}>Edit</Button>}
          <Button onClick={closeModal}>Cancel</Button>
        </div>
      </EditorWrapper>
    </Modal>
  )
}

export default HtmlPreviewModal
