import React, { useState, useEffect, useMemo, useCallback } from 'react'
import { Row, Icon, Tag, Divider, notification, Spin, Col, Button } from 'antd'
import QueryString from 'query-string'
import moment from 'moment-timezone'
import { useLoaderContextValue, useErrorContextValue, resetError } from '@pasarpolis/common-react-hooks'
import { useCreateDocument, useGetDocumentList, useEditDocument, useGetDocumentListCount, useResetState } from '../../state/hooks/useDocumentContext'
import LayoutContentWrapper from '../../../../../components/utility/layoutWrapper'
import TableWrapper from '../../pagination.style'
import QuerySearchBuilder from '../../../../../helpers/querySearchBuilder'
import {
  FilterInput
} from '../../../../../components/tables/helperCells'
import DocGenrationListWrapper from './style'
import CreateDocumentModal from '../../component/CreateDocumentModal/CreateDocumentModal'
import EditDocumentModal from '../../component/EditDocumentModal/EditDocumentModal'
import HtmlPreviewModal from '../../component/HtmlPreviewModal'

const DocumentList = ({ location, history, match }) => {
  const [filterActive, setFilterActive] = useState(false)
  const [searchTextQuery, setSearchTextQuery] = useState({})
  const [appliedFilter, setAppliedFilter] = useState({})

  const [{ getDocListData = [] }, getDocumentListRequest] = useGetDocumentList()
  const [{ getDocCountData = {} }, getDocumentListCountRequest] = useGetDocumentListCount()
  const [, createDocumentRequest] = useCreateDocument()
  const [, editDocumentRequest] = useEditDocument()

  const [{ GET_DOC_LIST_LOADER, CREATE_DOC_LOADER, EDIT_DOC_LOADER }] = useLoaderContextValue()

  const [
    {
      CREATE_DOC_ERROR = '',
      GET_DOC_LIST_ERROR = '',
      EDIT_DOC_ERROR = '',
      getDocListStatus,
      createDocErrorData,
      createDocStatus,
      editDocErrorData,
      editDocStatus
    },
    dispatchError
  ] = useErrorContextValue()

  const [resetState] = useResetState()

  const [createDocumentModalState, setCreateDocumentModalState] = useState(false)
  const [EditDocumentModalState, setEditDocumentModalState] = useState(false)
  const [editFormValues, setEditFormValues] = useState({})

  const [htmlContent, setHtmlContent] = useState('')
  const [htmlContentData, setHtmlContentData] = useState({})
  const [viewModal, setViewModal] = useState(false)
  const [htmlPreviewModal, setHtmlPreviewModal] = useState(false)
  const [onlyView, setOnlyView] = useState(false)

  const summaryData = useMemo(() => {
    return getDocListData && Array.isArray(getDocListData) ? getDocListData : []
  }, [getDocListData])

  useEffect(() => {
    const querySearch = QueryString.parse(location?.search)
    fetch(querySearch)

    setSearchTextQuery({ ...querySearch })
    setAppliedFilter({ ...querySearch })

    return () => resetState(['getDocListData'])
  }, [])

  // Error While fetching Document List
  useEffect(() => {
    if (GET_DOC_LIST_ERROR) {
      notification.error({
        message: getDocListStatus
      })
      dispatchError(
        resetError({
          GET_DOC_LIST_ERROR: '',
          getDocListStatus: ''
        })
      )
    }
  }, [GET_DOC_LIST_ERROR, getDocListStatus])

  // Error Handing While Generating Document
  useEffect(() => {
    if (CREATE_DOC_ERROR) {
      if (
        createDocErrorData &&
        createDocErrorData?.errors?.length &&
        createDocErrorData?.errors[0]?.description
      ) {
        createDocErrorData?.errors[0]?.description?.code[0] &&
          notification.error({
            message: createDocErrorData?.errors[0]?.description?.code[0]
          })
      } else {
        createDocStatus && notification.error({ message: createDocStatus })
      }
    } else if (!CREATE_DOC_ERROR && createDocStatus === 'success') {
      createDocStatus && notification.success({ message: createDocStatus })
      setCreateDocumentModalState(false)
      getDocumentListRequest()
      setCreateDocumentModalState(false)
    }

    dispatchError(
      resetError({
        CREATE_DOC_ERROR: '',
        createDocStatus: '',
        createDocErrorData: ''
      })
    )
  }, [CREATE_DOC_ERROR, createDocErrorData, createDocStatus])

  // Error handling While Editing document
  useEffect(() => {
    if (EDIT_DOC_ERROR) {
      if (editDocErrorData && editDocErrorData?.error) {
        notification.error({
          message: createDocErrorData?.error
        })
      } else {
        editDocStatus && notification.error({
          message: editDocStatus
        })
      }
    } else if (!EDIT_DOC_ERROR && editDocStatus === 'success') {
      notification.success({
        message: editDocStatus
      })
      getDocumentListRequest()
      setHtmlContent('')
      setHtmlContentData({})
      setHtmlPreviewModal(false)
      handleEditModal({}, false)
    }
    dispatchError(
      resetError({
        EDIT_DOC_ERROR: false,
        editDocStatus: '',
        editDocErrorData: ''
      })
    )
  }, [EDIT_DOC_ERROR, editDocErrorData, editDocStatus])

  const fetch = useCallback((params = {}) => {
    const { page } = params
    const pageNumber = Number(page) || 1
    delete params.page

    getDocumentListCountRequest({
      query: {
        ...params
      }
    })

    getDocumentListRequest({
      query: {
        ...params,
        page_number: pageNumber
      }
    })
  }, [])

  const handlePageChange = useCallback(
    (page) => {
      const querySearch = QueryString.parse(location?.search)
      const searchText = { ...querySearch, page: page }

      const search = QuerySearchBuilder(searchText)
      history.push({ pathname: location?.pathname, search })
      fetch(searchText)
    },
    [QueryString, location]
  )

  const renderTitle = (titleClass, text) => {
    return (
      <div className={titleClass}>
        <span>{text}</span>
      </div>
    )
  }

  const handleHtmlModal = (data, state, onlyView) => {
    setHtmlContent(data?.html)
    setHtmlContentData(data)
    setOnlyView(onlyView)
    setHtmlPreviewModal(state)
  }

  const handleHtmlView = (data) => {
    return (
      <div className='html-view-button'>
        <Button onClick={() => handleHtmlModal(data, true, false)}>View</Button>
      </div>
    )
  }

  const handleHtmlContentChange = (val) => {
    setHtmlContent(val)
  }

  const handleEditModal = (data, state, viewState) => {
    setEditFormValues(data)
    setViewModal(viewState)
    setEditDocumentModalState(state)
  }

  const onInputChange = useCallback(
    (value, identifier) => {
      setSearchTextQuery({
        ...searchTextQuery,
        [identifier]: value
      })
    },
    [searchTextQuery, setSearchTextQuery]
  )

  const clearQuerySearchBuilder = useCallback(
    (identifier) => {
      const oldSearch = QueryString.parse(location?.search)
      delete oldSearch[identifier]
      const search = QuerySearchBuilder(oldSearch)
      history.push({ pathname: location?.pathname, search })
      return oldSearch
    },
    [location]
  )

  const onSearch = useCallback(
    (e, key) => {
      e.preventDefault()

      getDocumentListCountRequest({
        query: {
          code: searchTextQuery?.code
        }
      })

      getDocumentListRequest({
        query: {
          code: searchTextQuery?.code
        }
      })

      const searchText = { ...searchTextQuery }
      const search = QuerySearchBuilder(searchText)
      history.push({ pathname: location?.pathname, search })
      fetch(searchText)
      setFilterActive({ ...filterActive, [key]: false })
      setAppliedFilter(searchTextQuery)
    },
    [searchTextQuery, filterActive]
  )

  const clearFilter = useCallback(
    (identifier) => {
      const searchText = {
        ...searchTextQuery,
        [identifier]: undefined
      }
      setSearchTextQuery(searchText)
      setAppliedFilter(searchText)
      const oldSearch = clearQuerySearchBuilder(identifier)
      fetch(oldSearch)
    },
    [
      searchTextQuery,
      clearQuerySearchBuilder,
      getDocumentListRequest,
      setAppliedFilter,
      setSearchTextQuery
    ]
  )

  const columns = [
    {
      key: 'View',
      title: renderTitle('with-margin', 'View'),
      render: (data) => (
        <Icon
          type='eye'
          theme='twoTone'
          className='edit-icon'
          onClick={() => handleEditModal(data, true, true)}
        />

      )
    },
    {
      key: 'action',
      title: renderTitle('with-margin', 'Action'),
      render: (data) => (
        <Icon
          type='edit'
          theme='twoTone'
          className='edit-icon'
          onClick={() => handleEditModal(data, true, false)}
        />
      )
    },
    {
      key: 'code',
      title: renderTitle('title-with-margin', 'Code'),
      dataIndex: 'code',
      filterDropdown: (
        <FilterInput
          idIdentifier='code'
          searchText={searchTextQuery.code ? searchTextQuery.code : undefined}
          onInputChange={(e) => onInputChange(e.target.value, 'code')}
          onSearch={(e) => onSearch(e, 'code')}
        />
      ),
      filterIcon: (
        <Icon type='filter' theme='outlined' className='filter-icon' />
      ),
      filterDropdownVisible: filterActive?.code,
      onFilterDropdownVisibleChange: (visible) =>
        setFilterActive({ ...filterActive, code: visible })
    },
    {
      key: 'display_name',
      title: 'Display Name',
      dataIndex: 'display_name'
    },
    {
      key: 'version',
      title: 'HTML Version',
      dataIndex: 'version'
    },
    {
      key: 'active',
      title: 'Active',
      dataIndex: 'active',
      render: (data) => (data ? 'True' : 'False')
    },
    {
      key: 'html',
      title: 'HTML',
      render: (data) => handleHtmlView(data)
    },
    {
      key: 'reference_doc',
      title: 'Reference Doc',
      dataIndex: 'reference_doc'
    },
    {
      key: 'reference_doc_url',
      title: 'Reference Doc URL',
      dataIndex: 'reference_doc_url'
    },
    {
      key: 'static_pdf',
      title: 'Static PDF',
      dataIndex: 'static_pdf'
    },
    {
      key: 'static_pdf_url',
      title: 'Static PDF URL',
      dataIndex: 'static_pdf_url'
    },
    {
      key: 'created_at',
      title: 'Created At',
      dataIndex: 'created_at',
      render: (date) => moment(date).tz('Asia/Jakarta').format('lll')
    }
  ]

  return (
    <LayoutContentWrapper className='referral-table'>
      <DocGenrationListWrapper>
        <Spin spinning={!!GET_DOC_LIST_LOADER}>
          <Row type='flex' align='middle'>
            <Col sm={4} md={8}>
              <h3 className='heading'>
                <b>Document Generation Service</b>
              </h3>
            </Col>
            <Col sm={20} md={16}>
              <div className='doc-wrapper'>
                <Button
                  onClick={() => {
                    setHtmlPreviewModal(true)
                    setOnlyView(true)
                  }}
                >
                  HTML Preview
                </Button>
                <Button
                  onClick={() => setCreateDocumentModalState(true)}
                  className='button-text'
                >
                  Add New Document
                </Button>
              </div>
            </Col>
            <Divider />

            {appliedFilter &&
              Object.keys(appliedFilter).map((key, index) => {
                if (appliedFilter[key]) {
                  return (
                    <Tag key={index} className='filter-tag' color='blue'>
                      {appliedFilter[key]}
                      <span
                        className='remove-filter'
                        onClick={(e) => clearFilter(key)}
                      >
                        <Icon type='close' className='close' />
                      </span>
                    </Tag>
                  )
                } else {
                  return ''
                }
              })}

            <TableWrapper
              dataSource={summaryData}
              rowKey={(record) => record.id}
              pagination={{
                pageSize: 10,
                total: Number(getDocCountData?.metadata?.total_records),
                onChange: (page) => {
                  handlePageChange(page)
                }
              }}
              columns={columns}
            />

            <CreateDocumentModal
              closeModal={() => setCreateDocumentModalState(false)}
              isOpen={createDocumentModalState}
              createDocumentRequest={createDocumentRequest}
              CREATE_DOC_LOADER={!!CREATE_DOC_LOADER}
            />

            <EditDocumentModal
              closeModal={() => handleEditModal({}, false, viewModal)}
              viewOnly={viewModal}
              setViewModal={setViewModal}
              isOpen={EditDocumentModalState}
              editDocumentRequest={editDocumentRequest}
              LOADER={!!CREATE_DOC_LOADER && !!EDIT_DOC_LOADER}
              dataValues={editFormValues}
            />

            <HtmlPreviewModal
              closeModal={() => handleHtmlModal('', false, true)}
              isOpen={htmlPreviewModal}
              htmlContent={htmlContent}
              handleHtmlContentChange={handleHtmlContentChange}
              htmlContentData={htmlContentData}
              editDocumentRequest={editDocumentRequest}
              LOADER={!!CREATE_DOC_LOADER && !!EDIT_DOC_LOADER}
              onlyView={onlyView}
            />
          </Row>
        </Spin>
      </DocGenrationListWrapper>
    </LayoutContentWrapper>
  )
}

export default DocumentList
