import React, { createContext, useContext, useReducer } from 'react'
import reducer, { INITIAL_STATE } from '../state/reducer'

export const DocumentContext = createContext()

export const DocumentContextProvider = (props) => {
  return (
    <DocumentContext.Provider value={useReducer(reducer, INITIAL_STATE)}>
      {props.children}
    </DocumentContext.Provider>
  )
}

export const useDocumentContextValue = () => useContext(DocumentContext)
