import React, { useCallback } from 'react'
import { Modal, Form, Input, Select, Button } from 'antd'
import DocumentModalWrapper from '../style'

const { TextArea } = Input

const CreateDocumentModal = ({
  isOpen,
  closeModal,
  form,
  createDocumentRequest,
  CREATE_DOC_LOADER
}) => {
  const { getFieldDecorator } = form

  const validateForm = useCallback(async () => {
    return new Promise((resolve) => {
      form.validateFields((error) => {
        resolve(!error)
      })
    })
  }, [form])

  const handleSubmit = useCallback(
    async (e) => {
      e.preventDefault()
      const valid = await validateForm()
      if (!valid) return
      const formValues = {
        ...form.getFieldsValue()
      }
      createDocumentRequest({
        body: { ...formValues }
      })
    },
    [validateForm, form, createDocumentRequest]
  )

  return (
    <Modal
      title='Create Document'
      visible={isOpen}
      onCancel={closeModal}
      footer={null}
      afterClose={() => form.resetFields()}
    >
      <DocumentModalWrapper>
        <Form onSubmit={handleSubmit}>
          <label>Code</label>
          <Form.Item>
            {getFieldDecorator('code', {
              rules: [{ required: true, message: 'Code can not be empty' }]
            })(<Input placeholder='Code' />)}
          </Form.Item>

          <label>Display Name</label>
          <Form.Item>
            {getFieldDecorator('display_name', {
              rules: [{ required: true, message: 'Display Name can not be empty' }]
            })(<TextArea rows={3} placeholder='Name' />)}
          </Form.Item>

          <label>Reference Doc</label>
          <Form.Item>
            {getFieldDecorator('reference_doc', {
              rules: [{ required: false, message: 'Reference Doc can not be empty' }]
            })(<Input placeholder='Reference Doc' />)}
          </Form.Item>

          <label>Reference Doc URL</label>
          <Form.Item>
            {getFieldDecorator('reference_doc_url', {
              rules: [{ required: false, message: 'Reference Doc URL can not be empty' }]
            })(<Input placeholder='Reference Doc URL' />)}
          </Form.Item>

          <label>Static PDF</label>
          <Form.Item>
            {getFieldDecorator('static_pdf', {
              rules: [{ required: false }]
            })(<Input placeholder='Static PDF' />)}
          </Form.Item>

          <label>Static PDF URL</label>
          <Form.Item>
            {getFieldDecorator('static_pdf_url', {
              rules: [{ required: false }]
            })(<Input placeholder='Static PDF URL' />)}
          </Form.Item>

          <label>HTML Version</label>
          <Form.Item>
            {getFieldDecorator('version', {
              rules: [{ required: false }]
            })(
              <Select placeholder='HTML Version'>
                <Select.Option value={1}>1 (pdfkit)</Select.Option>
                <Select.Option value={2}>2 (weasyprint)</Select.Option>
              </Select>
            )}
          </Form.Item>

          <label>HTML</label>
          <Form.Item>
            {getFieldDecorator('html', {
              rules: [{ required: true, message: 'html can not be empty' }]
            })(<TextArea rows={4} placeholder='HTML' />)}
          </Form.Item>

          <Button
            key='submit'
            type='primary'
            htmlType='submit'
            className='form-submit'
            loading={CREATE_DOC_LOADER}
          >
            Submit
          </Button>
        </Form>
      </DocumentModalWrapper>
    </Modal>
  )
}

export default Form.create({})(CreateDocumentModal)
