import React, { useCallback } from 'react'
import { Modal, Form, Input, Select, Button, Icon } from 'antd'
import { get } from 'lodash'
import DocumentModalWrapper from '../style'

const { TextArea } = Input

const EditDocumentModal = ({
  isOpen,
  closeModal,
  form,
  editDocumentRequest,
  viewOnly,
  dataValues,
  LOADER,
  setViewModal
}) => {
  const { getFieldDecorator } = form

  const validateForm = useCallback(async () => {
    return new Promise((resolve) => {
      form.validateFields((error) => {
        resolve(!error)
      })
    })
  }, [form])

  const handleSubmit = useCallback(
    async (e) => {
      e.preventDefault()
      const valid = await validateForm()
      if (!valid) return
      const formValues = {
        ...form.getFieldsValue()
      }
      editDocumentRequest({
        body: { ...formValues }
      })
    },
    [validateForm, form, editDocumentRequest]
  )

  return (
    <Modal
      title={`${viewOnly ? 'View Document' : 'Edit Document'}`}
      visible={isOpen}
      onCancel={closeModal}
      footer={null}
      afterClose={() => form.resetFields()}
    >
      <DocumentModalWrapper>
        {viewOnly &&
          <div className='edit-section'>
            <Icon type='edit' theme='twoTone' className='icon' onClick={() => setViewModal(false)} />
          </div>}
        <Form onSubmit={handleSubmit}>
          <label>Code</label>
          <Form.Item>
            {getFieldDecorator('code', {
              rules: [{ required: true, message: 'Code can not be empty' }],
              initialValue: get(dataValues, 'code')
            })(<Input placeholder='Code' disabled />)}
          </Form.Item>

          <label>Display Name</label>
          <Form.Item>
            {getFieldDecorator('display_name', {
              rules: [{ required: true, message: 'Display Name can not be empty' }],
              initialValue: get(dataValues, 'display_name')
            })(<TextArea rows={3} placeholder='Name' disabled={viewOnly} />)}
          </Form.Item>

          <label>Reference Doc</label>
          <Form.Item>
            {getFieldDecorator('reference_doc', {
              rules: [{ required: false, message: 'Reference Doc can not be empty' }],
              initialValue: get(dataValues, 'reference_doc')
            })(<Input placeholder='Reference Doc' disabled={viewOnly} />)}
          </Form.Item>

          <label>Reference Doc URL</label>
          <Form.Item>
            {getFieldDecorator('reference_doc_url', {
              rules: [{ required: false, message: 'Reference Doc URL can not be empty' }],
              initialValue: get(dataValues, 'reference_doc_url')
            })(<Input placeholder='Reference Doc URL' disabled={viewOnly} />)}
          </Form.Item>

          <label>Static PDF</label>
          <Form.Item>
            {getFieldDecorator('static_pdf', {
              rules: [{ required: false }],
              initialValue: get(dataValues, 'static_pdf')
            })(<Input placeholder='Static PDF' disabled={viewOnly} />)}
          </Form.Item>

          <label>Static PDF URL</label>
          <Form.Item>
            {getFieldDecorator('static_pdf_url', {
              rules: [{ required: false }],
              initialValue: get(dataValues, 'static_pdf_url')
            })(<Input placeholder='Static PDF URL' disabled={viewOnly} />)}
          </Form.Item>

          <label>HTML Version</label>
          <Form.Item>
            {getFieldDecorator('version', {
              rules: [{ required: false }],
              initialValue: get(dataValues, 'version')
            })(
              <Select placeholder='HTML Version'>
                <Select.Option value={1}>1 (pdfkit)</Select.Option>
                <Select.Option value={2}>2 (weasyprint)</Select.Option>
              </Select>
            )}
          </Form.Item>

          <label>HTML</label>
          <Form.Item>
            {getFieldDecorator('html', {
              rules: [{ required: true, message: 'html can not be empty' }],
              initialValue: get(dataValues, 'html')
            })(<TextArea rows={4} placeholder='HTML' disabled={viewOnly} />)}
          </Form.Item>

          <div className='button-area'>
            <Button
              key='submit'
              type='primary'
              htmlType='submit'
              className='form-submit'
              disabled={viewOnly}
              loading={LOADER}
            >
              Submit
            </Button>
          </div>
        </Form>
      </DocumentModalWrapper>
    </Modal>
  )
}

export default Form.create({})(EditDocumentModal)
