import urls from '../../../../config/urls'
const configUrl = urls.url

export const ACTIONS = {
  GET_DOC_LIST: 'GET_DOC_LIST',
  GET_DOC_LIST_REQUEST: 'GET_DOC_LIST_REQUEST',

  CREATE_DOC: 'CREATE_DOC',
  CREATE_DOC_REQUEST: 'CREATE_DOC_REQUEST',

  EDIT_DOC: 'EDIT_DOC',
  EDIT_DOC_REQUEST: 'EDIT_DOC_REQUEST',

  GET_DOC_COUNT: 'GET_DOC_COUNT',
  GET_DOC_COUNT_REQUEST: 'GET_DOC_COUNT_REQUEST',

  RESET_REDUX_STATE_DOC: 'RESET_REDUX_STATE_DOC',

  getDocumentList: (payload) => ({
    type: ACTIONS.GET_DOC_LIST_REQUEST,
    payload: {
      ...payload,
      method: 'get',
      url: configUrl.documentGenerationList
    }
  }),
  createDocument: (payload) => ({
    type: ACTIONS.CREATE_DOC_REQUEST,
    payload: {
      ...payload,
      method: 'post',
      url: configUrl.documentGenerationCreate
    }
  }),
  editDocument: (payload) => ({
    type: ACTIONS.EDIT_DOC_REQUEST,
    payload: {
      ...payload,
      method: 'post',
      url: configUrl.documentGenerationEdit
    }
  }),
  getDocumentListCount: (payload) => ({
    type: ACTIONS.GET_DOC_COUNT_REQUEST,
    payload: {
      ...payload,
      method: 'get',
      url: configUrl.documentGenerationListCount
    }
  }),
  resetReduxStateDoc: (keys) => ({
    type: ACTIONS.RESET_REDUX_STATE_DOC,
    payload: keys
  })
}
