import { useServiceRequest } from '@pasarpolis/common-react-hooks'

import { useDocumentContextValue } from '../../context'
import { ACTIONS } from '../actions'

export const useDocumentServiceCall = (actionsCall = () => {}) => {
  const [documentState, dispatch] = useDocumentContextValue()
  const [callApi] = useServiceRequest(dispatch)
  const request = async (payload = {}) => {
    await callApi(
      actionsCall({
        ...payload
      })
    )
  }

  return [documentState, request]
}

export const useGetDocumentList = () => {
  return useDocumentServiceCall(ACTIONS.getDocumentList)
}

export const useCreateDocument = () => {
  return useDocumentServiceCall(ACTIONS.createDocument)
}

export const useEditDocument = () => {
  return useDocumentServiceCall(ACTIONS.editDocument)
}

export const useGetDocumentListCount = () => {
  return useDocumentServiceCall(ACTIONS.getDocumentListCount)
}

export const useResetState = () => {
  const [, dispatch] = useDocumentContextValue()
  const resetState = (keys = []) => {
    dispatch(ACTIONS.resetReduxStateDoc)
  }
  return [resetState]
}
